# Decompose "cut claim settlement time from 10 days to 5" and rank the leaves.
tree = {
    "Cut settlement time 10d -> 5d": {
        "Intake (2.5 days)": {
            "Auto-extract fields from claim PDFs": dict(impact=7, confidence=0.8, effort=3, ai=True),
            "Sync intake form straight to policy system": dict(impact=6, confidence=0.9, effort=1, ai=False),
        },
        "Assessment (5 days)": {
            "Summarise claim history for adjusters": dict(impact=5, confidence=0.7, effort=2, ai=True),
            "Auto-approve low-risk claims": dict(impact=9, confidence=0.4, effort=6, ai=True),
        },
        "Payout (2.5 days)": {
            "Batch payments daily instead of weekly": dict(impact=6, confidence=0.95, effort=1, ai=False),
        },
    }
}

def leaves(node, path=()):
    for name, child in node.items():
        if "impact" in child:
            yield path + (name,), child
        else:
            yield from leaves(child, path + (name,))

def show(node, depth=0):
    for name, child in node.items():
        print("  " * depth + ("- " if depth else "") + name)
        if "impact" not in child:
            show(child, depth + 1)

show(tree)
ranked = sorted(leaves(tree), key=lambda x: -x[1]["impact"] * x[1]["confidence"] / x[1]["effort"])
print("\nRanked by impact x confidence / effort:")
for path, s in ranked:
    score = s["impact"] * s["confidence"] / s["effort"]
    tag = "AI " if s["ai"] else "   "
    print(f"  {score:4.1f}  {tag} {path[-1]}")
